package mls.sho.dms.application.purchasing.service;

import mls.sho.dms.application.purchasing.repository.GoodsReceiptRepository;
import mls.sho.dms.common.enums.GoodsReceiptStatus;
import mls.sho.dms.entity.GoodsReceipt;
import mls.sho.dms.entity.Restaurant;
import mls.sho.dms.entity.Supplier;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class GoodsReceiptServiceStaleGRNsTest {

    @Mock
    private GoodsReceiptRepository goodsReceiptRepository;

    @InjectMocks
    private GoodsReceiptService goodsReceiptService;

    private Restaurant restaurant;
    private Supplier supplier;

    @BeforeEach
    void setUp() {
        restaurant = new Restaurant();
        restaurant.setId(1L);

        supplier = new Supplier();
        supplier.setId(1L);
        supplier.setName("Test Supplier");
    }

    @Test
    void getStaleGRNs_returnsRecentUnmatchedGRNs() {
        GoodsReceipt recentGRN = createGRN(1L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now());
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(Collections.singletonList(recentGRN));
        List<GoodsReceipt> result = goodsReceiptService.getStaleGRNs(1L);
        assertEquals(1, result.size());
        assertEquals(1L, result.get(0).getId());
    }

    @Test
    void getStaleGRNs_returnsAllUnmatchedGRNsRegardlessOfAge() {
        GoodsReceipt recentGRN = createGRN(1L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now());
        GoodsReceipt yesterdayGRN = createGRN(2L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now().minusDays(1));
        GoodsReceipt weekOldGRN = createGRN(3L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now().minusDays(7));
        GoodsReceipt monthOldGRN = createGRN(4L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now().minusDays(30));
        List<GoodsReceipt> allUnmatchedGRNs = Arrays.asList(recentGRN, yesterdayGRN, weekOldGRN, monthOldGRN);
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(allUnmatchedGRNs);
        List<GoodsReceipt> result = goodsReceiptService.getStaleGRNs(1L);
        assertEquals(4, result.size());
    }

    @Test
    void getStaleGRNs_excludesMatchedGRNs() {
        GoodsReceipt unmatchedGRN = createGRN(1L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now());
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(Collections.singletonList(unmatchedGRN));
        List<GoodsReceipt> result = goodsReceiptService.getStaleGRNs(1L);
        assertEquals(1, result.size());
        assertEquals(1L, result.get(0).getId());
    }

    @Test
    void getStaleGRNs_excludesDraftGRNs() {
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(Collections.emptyList());
        List<GoodsReceipt> result = goodsReceiptService.getStaleGRNs(1L);
        assertTrue(result.isEmpty());
    }

    @Test
    void getStaleGRNs_returnsEmptyListWhenAllGRNsMatched() {
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(Collections.emptyList());
        List<GoodsReceipt> result = goodsReceiptService.getStaleGRNs(1L);
        assertTrue(result.isEmpty());
    }

    @Test
    void getStaleGRNs_countConsistencyWithRepositoryCount() {
        GoodsReceipt grn1 = createGRN(1L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now());
        GoodsReceipt grn2 = createGRN(2L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now().minusDays(5));
        GoodsReceipt grn3 = createGRN(3L, GoodsReceiptStatus.RECEIVED, LocalDateTime.now().minusDays(30));
        List<GoodsReceipt> unmatchedGRNs = Arrays.asList(grn1, grn2, grn3);
        when(goodsReceiptRepository.findStaleGRNs(1L)).thenReturn(unmatchedGRNs);
        when(goodsReceiptRepository.countUnmatchedGRNs(1L)).thenReturn(3);
        List<GoodsReceipt> staleGRNs = goodsReceiptService.getStaleGRNs(1L);
        int unmatchedCount = goodsReceiptRepository.countUnmatchedGRNs(1L);
        assertEquals(unmatchedCount, staleGRNs.size());
        assertEquals(3, staleGRNs.size());
    }

    private GoodsReceipt createGRN(Long id, GoodsReceiptStatus status, LocalDateTime receivedDate) {
        GoodsReceipt grn = new GoodsReceipt();
        grn.setId(id);
        grn.setRestaurant(restaurant);
        grn.setSupplier(supplier);
        grn.setStatus(status);
        grn.setReceivedDate(receivedDate);
        grn.setTotalAmount(BigDecimal.valueOf(100.00));
        return grn;
    }
}
